import {TACTICS,DESCRIPTIONS,ATTRS,createMatch,beginTurn,resolve,baseAttacks,displayAttacks,statusLabels,activated,rng} from './engine.js';
import {chooseCpu} from './cpu.js';
const app=document.querySelector('#app'),detail=document.querySelector('#detail-dialog'),rules=document.querySelector('#rules-dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,step=0,charId=160,tactics=[],focus=160,query='',filter='',page=0,phase='setup',match=null,cpuAction=null,chosenSlot=-1,random=Math.random,notice='';
const tone=['fire','leaf','water'];const perPage=24;
const card=id=>data.cards[id];
const cardLabel=c=>c.type?`${c.character} · ${TACTICS[c.type]}`:`${c.character} · ${c.rarity}`;
const stats=values=>`<div class="stats">${values.map((n,i)=>`<div class="stat ${tone[i]}"><span>${ATTRS[i]}</span><strong>${n}</strong></div>`).join('')}</div>`;
const image=(c,extra='',back=false)=>`<img ${extra} src="${back&&c.backImage?c.backImage:c.image}" alt="${esc(c.name)}" width="384" height="512">`;
document.querySelector('#rules-open').addEventListener('click',()=>rules.showModal());
for(const modal of [detail,rules]){modal.addEventListener('click',e=>{if(e.target===modal||e.target.closest('[data-close]'))modal.close();});}
function showDetail(id,back=false){const c=card(id);detail.innerHTML=`<div class="dialog-head"><h2>${esc(cardLabel(c))}</h2><button class="quiet" data-close>閉じる</button></div><div class="detail-layout">${image(c,'',back)}<div><div class="card-code">${esc(c.name)}</div>${c.type?`<p>${esc(DESCRIPTIONS[c.type])}</p>`:stats(c.atk.map(v=>v+(back?50:0)))}${c.ssr?'<p class="muted">5ターン目に変身し、全属性の攻撃力が50上がります。</p>':''}${c.growth?'<p class="muted">毎ターン、ランダムな属性の基礎攻撃力＋50。勝った属性はさらに＋50。</p>':''}</div></div>`;detail.showModal();}
function renderSetup(){phase='setup';app.innerHTML=`<section class="setup-heading"><h1>デッキを選ぶ</h1><nav class="steps" aria-label="デッキ選択"><button data-step="0" class="${step===0?'active':''}"><span class="step-no">01</span>キャラ 1枚</button><button data-step="1" class="${step===1?'active':''}"><span class="step-no">02</span>戦術 3枚</button></nav></section><div class="setup-layout"><aside class="selection-panel" id="selection"></aside><section class="catalog"><div class="filters"><input id="search" type="search" aria-label="カードを検索" placeholder="キャラ名・カード名で検索" value="${esc(query)}"><select id="filter" aria-label="${step===0?'レアリティ':'戦術の効果'}で絞り込み"><option value="">${step===0?'すべてのレアリティ':'すべての戦術'}</option>${(step===0?['R','SR','USR','SUSR','SSR'].map(v=>[v,v]):TACTICS.slice(1).map((v,i)=>[String(i+1),v])).map(([v,label])=>`<option value="${v}" ${filter===v?'selected':''}>${esc(label)}</option>`).join('')}</select></div><div class="catalog-top"><span id="catalog-count"></span><span>カードを押して選択</span></div><div class="card-grid" id="card-grid"></div><div class="pagination" id="pagination"></div></section></div>`;renderSelection();renderCatalog();}
function renderSelection(){const c=card(focus);document.querySelector('#selection').innerHTML=`${image(c,'class="focus-image" tabindex="0" role="button" aria-label="カードを拡大" data-detail="'+c.id+'"')}<div class="focus-info"><div class="focus-title">${esc(cardLabel(c))}</div><div class="card-code">${esc(c.name)}</div>${c.type?`<p class="focus-description">${esc(DESCRIPTIONS[c.type])}</p>`:stats(c.atk)}${c.growth?'<p class="muted">ターン終了ごとに攻撃力が成長</p>':''}${c.ssr?'<p class="muted">5ターン目に変身・全属性＋50</p>':''}</div><div class="deck-selection"><p class="deck-label">選出戦術 <b>${tactics.length}/3</b></p><div class="deck-slots">${[0,1,2].map(i=>tactics[i]!==undefined?`<button class="deck-slot filled" data-remove="${i}" aria-label="${esc(cardLabel(card(tactics[i])))}を外す">${image(card(tactics[i]))}<span class="slot-x">×</span></button>`:`<div class="deck-slot" aria-label="戦術${i+1} 未選択">${i+1}</div>`).join('')}</div></div><div class="notice" role="status">${esc(notice)}</div><button class="primary" data-action="${step===0?'tactics':'start'}" ${step===1&&tactics.length!==3?'disabled':''}>${step===0?'戦術を選ぶ':'CPUと対戦する'}</button>`;}
function filtered(){const q=query.trim().toLowerCase();return data.cards.filter(c=>(step===0?c.type===0:c.type>0)&&(!filter||(step===0?c.rarity===filter:c.type===Number(filter)))&&(!q||`${c.name} ${c.character} ${TACTICS[c.type]}`.toLowerCase().includes(q)));}
function renderCatalog(){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/perPage));page=Math.min(page,pages-1);document.querySelector('#catalog-count').textContent=`${list.length}枚${step===0?' · キャラ1枚を選択':' · 異なるカードを3枚選択'}`;document.querySelector('#card-grid').innerHTML=list.length?list.slice(page*perPage,(page+1)*perPage).map(c=>{const selected=step===0?c.id===charId:tactics.includes(c.id);return `<button class="catalog-card ${selected?'selected':''}" data-select="${c.id}" aria-label="${esc(cardLabel(c))} ${esc(c.name)}" aria-pressed="${selected}">${image(c,'loading="lazy" decoding="async"')}${selected?'<span class="selection-check">✓</span>':''}<span class="name">${esc(c.character)}${c.type?'':` <small>${c.rarity}</small>`}</span><span class="meta">${c.type?TACTICS[c.type]:esc(c.name.split('_').slice(2).join('_'))}</span>${!c.type?`<span class="mini-stats">${c.atk.map((v,i)=>`<span class="${tone[i]}">${ATTRS[i]} ${v}</span>`).join('')}</span>`:''}</button>`;}).join(''):'<p class="empty">該当するカードがありません。</p>';document.querySelector('#pagination').innerHTML=`<button data-page="-1" ${page===0?'disabled':''}>前へ</button><span>${page+1} / ${pages}</span><button data-page="1" ${page===pages-1?'disabled':''}>次へ</button>`;}
function changeStep(n){step=n;page=0;query='';filter='';notice='';focus=n===0?charId:tactics[0]??0;renderSetup();}
function select(id){const c=card(id);focus=id;notice='';if(step===0)charId=id;else if(tactics.includes(id))tactics=tactics.filter(v=>v!==id);else if(tactics.length<3)tactics.push(id);else notice='3枚選択済みです。外すカードを押してください。';renderSelection();renderCatalog();}
function start(){if(tactics.length!==3)return;const seed=crypto.getRandomValues(new Uint32Array(1))[0];random=rng(seed);const chars=data.cards.filter(c=>c.type===0),all=data.cards.filter(c=>c.type>0);const cpuChar=chars[Math.floor(random()*chars.length)].id,cpuDeck=[];while(cpuDeck.length<3){const id=all[Math.floor(random()*all.length)].id;if(!cpuDeck.includes(id))cpuDeck.push(id);}match=createMatch(data,[charId,cpuChar],[[...tactics],cpuDeck]);nextTurn();window.scrollTo({top:0,behavior:'instant'});}
function nextTurn(){beginTurn(match,data);cpuAction=chooseCpu(match,data,random);chosenSlot=-1;phase='tactic';renderBattle();}
function fighter(i){const s=match.sides[i],c=card(s.card),pct=Math.max(0,Math.min(100,s.hp/data.settings.baseHP*100)),hpColor=pct>50?'var(--green)':pct>25?'#d6b456':'#e97966';return `<section class="fighter"><div class="fighter-heading"><strong>${i===0?'あなた':'CPU'}</strong><span>${esc(c.character)} · ${c.rarity}${s.transformed?' 変身':''}</span></div><div class="fighter-body">${image(c,'class="battle-card" tabindex="0" role="button" aria-label="キャラカードを拡大" data-detail="'+c.id+'" data-back="'+s.transformed+'"',s.transformed)}${stats(displayAttacks(s,data))}</div><div class="hp-wrap"><div class="hp-heading"><span class="muted">HP</span><div class="hp-number">${s.hp}<small> / ${data.settings.baseHP}</small></div></div><div class="hp-track" role="meter" aria-label="${i===0?'あなた':'CPU'}のHP" aria-valuenow="${s.hp}" aria-valuemin="0" aria-valuemax="${data.settings.baseHP}"><div class="hp-fill" style="width:${pct}%;background:${hpColor}"></div></div></div><div class="status-list">${statusLabels(s).map(v=>`<span class="status-tag ${/毒|睡眠|予告/.test(v)?'bad':''}">${esc(v)}</span>`).join('')||'<span class="muted">状態異常なし</span>'}</div></section>`;}
function renderBattle(){const r=match.history.at(-1),show=phase==='result';app.innerHTML=`<div class="battle-top"><div class="turn-label"><strong>${match.turn}</strong> ターン目</div><button class="quiet" data-action="exit">デッキ選択へ戻る</button></div><div class="arena">${fighter(0)}<div class="versus"><div class="vs">VS</div><div class="move-reveal">${show?`あなた <b class="${tone[r.moves[0]]}">${ATTRS[r.moves[0]]}</b><br>CPU <b class="${tone[r.moves[1]]}">${ATTRS[r.moves[1]]}</b>`:'戦術 → 属性 → 結果'}</div></div>${fighter(1)}</div><section class="action-panel" id="actions"></section><details class="history"><summary>対戦ログ${match.history.length?` · ${match.history.length}ターン`:''}</summary><ol>${match.history.map(h=>`<li>${h.turn}ターン：${ATTRS[h.moves[0]]} vs ${ATTRS[h.moves[1]]} ／ あなた −${h.damage[0]}、CPU −${h.damage[1]}<br>${h.used.map((id,i)=>`${i===0?'あなた':'CPU'}：${id<0?'戦術なし':TACTICS[card(id).type]}`).join(' ／ ')}</li>`).join('')||'<li>まだ結果はありません。</li>'}</ol></details><div class="live" role="status" aria-live="polite">${show?`${r.roundWinner===0?'引き分け':r.roundWinner===1?'あなたの属性勝利':'CPUの属性勝利'}。あなたのHP ${match.sides[0].hp}、CPUのHP ${match.sides[1].hp}`:phase==='tactic'?'戦術を選んでください':'属性を選んでください'}</div>`;renderActions();}
function renderActions(){const area=document.querySelector('#actions');if(phase==='tactic'){area.innerHTML=`<div class="action-head"><h2>戦術を選ぶ</h2><p>1枚につき1回。温存することもできます。</p></div><div class="tactic-hand">${match.sides[0].deck.map((d,i)=>{const c=card(d.id);return `<button class="tactic-choice ${d.left?'':'used'}" data-slot="${i}" ${d.left?'':'disabled'} aria-label="${TACTICS[c.type]} ${d.left?'を使う':'使用済み'}">${image(c)}<span><b>${TACTICS[c.type]}</b><span class="remain">${d.left?'使用できる':'使用済み'}</span><small>${esc(DESCRIPTIONS[c.type].split('\n')[0])}</small></span></button>`;}).join('')}<button class="none-choice quiet" data-slot="-1">戦術を使わない</button></div>`;}
 else if(phase==='attribute'){const a=displayAttacks(match.sides[0],data);area.innerHTML=`<div class="action-head"><div><h2>属性を選ぶ</h2><div class="chosen-note">${chosenSlot<0?'今回は戦術を使わない':`使用戦術：${TACTICS[card(match.sides[0].deck[chosenSlot].id).type]}`}</div></div><button class="quiet" data-action="back-tactic">戦術を選び直す</button></div><div class="attribute-choices">${ATTRS.map((name,i)=>`<button class="attribute-choice ${tone[i]}" data-move="${i}" aria-label="${name} 攻撃力${a[i]} を選ぶ"><span class="attr-name">${name}</span><strong>${a[i]}</strong><small>${ATTRS[(i+1)%3]}に勝つ</small></button>`).join('')}</div><p class="muted">数値は戦術の倍率・加算を適用する前の攻撃力です。</p>`;}
 else{const r=match.history.at(-1),finished=match.winner!==-1;const title=finished?(match.winner===0?'引き分け':match.winner===1?'あなたの勝利':'CPUの勝利'):(r.roundWinner===0?'属性は引き分け':r.roundWinner===1?'あなたの属性勝利':'CPUの属性勝利');area.innerHTML=`<div class="result-heading"><h2 class="result-title">${title}</h2>${!finished?'<button class="primary" data-action="next-turn">次のターンへ</button>':''}</div><div class="result-details">${[0,1].map(i=>`<div class="result-side"><strong>${i===0?'あなた':'CPU'} <span class="damage">−${r.damage[i]} HP</span></strong><p>${r.used[i]<0?'戦術なし':`${TACTICS[card(r.used[i]).type]} · ${activated(r,i)?'発動':'不発'}`}</p>${r.copied[i]>=0?`<p>体得 → ${TACTICS[card(r.copied[i]).type]}（再使用可）</p>`:''}${r.poisonTarget===i+1?'<p>毒を付与されました</p>':''}${r.foretellTarget===i+1?`<p>予告 ${r.foretellAmount}（3ターン後）</p>`:''}</div>`).join('')}</div>${finished?'<div class="finish-actions"><button class="primary" data-action="rematch">同じデッキでもう一度</button><button class="quiet" data-action="deck">デッキを組み直す</button></div>':''}`;}}
function chooseTactic(slot){if(phase!=='tactic')throw Error('戦術選択ではありません。');if(slot< -1||slot>2||(slot>=0&&!match.sides[0].deck[slot].left))throw Error('その戦術は使えません。');chosenSlot=slot;phase='attribute';renderActions();}
function chooseMove(move){if(phase!=='attribute')throw Error('属性選択ではありません。');resolve(match,data,[move,cpuAction.move],[chosenSlot,cpuAction.slot],random);phase='result';renderBattle();}
function confirmExit(){if(match?.winner===-1){detail.innerHTML='<div class="dialog-head"><h2>対戦を終了しますか？</h2><button class="quiet" data-close>続ける</button></div><p>進行中の対戦はリセットされます。</p><button class="primary" id="confirm-exit">デッキ選択へ戻る</button>';detail.showModal();document.querySelector('#confirm-exit').onclick=()=>{detail.close();changeStep(0);};}else changeStep(0);}
app.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;page=0;renderCatalog();}});
app.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;page=0;renderCatalog();}});
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-detail]')){e.preventDefault();showDetail(Number(e.target.dataset.detail),e.target.dataset.back==='true');}});
app.addEventListener('click',e=>{const el=e.target.closest('button,[data-detail]');if(!el||el.disabled)return;const d=el.dataset;
 if(d.detail!==undefined)return showDetail(Number(d.detail),d.back==='true');
 if(d.step!==undefined)return changeStep(Number(d.step));if(d.select!==undefined)return select(Number(d.select));
 if(d.remove!==undefined){tactics.splice(Number(d.remove),1);notice='';renderSelection();renderCatalog();return;}
 if(d.page!==undefined){page+=Number(d.page);renderCatalog();document.querySelector('.filters').scrollIntoView({block:'start',behavior:'instant'});return;}
 if(d.slot!==undefined)return chooseTactic(Number(d.slot));if(d.move!==undefined)return chooseMove(Number(d.move));
 switch(d.action){case'tactics':changeStep(1);break;case'start':case'rematch':start();break;case'back-tactic':phase='tactic';renderActions();break;case'next-turn':nextTurn();break;case'deck':changeStep(0);break;case'exit':confirmExit();break;}
});
function visibleState(){return {phase,turn:match?.turn??0,winner:match?.winner??-1,selectedCharacter:charId,selectedTactics:[...tactics],sides:match?.sides.map((s,i)=>({character:s.card,hp:s.hp,attacks:displayAttacks(s,data),statuses:statusLabels(s),...(i===0?{tactics:s.deck.map(d=>({id:d.id,remaining:d.left}))}:{})}))??[]};}
function webmcp(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'get_visible_battle_state',description:'Read the visible battle state. Never reveals CPU choices or hidden tactics.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>visibleState()},{name:'choose_player_tactic',description:'Choose an available tactic slot 0 to 2, or -1 to skip. Advances to attribute selection.',inputSchema:{type:'object',properties:{slot:{type:'integer',minimum:-1,maximum:2}},required:['slot'],additionalProperties:false},execute:({slot})=>{if(!Number.isInteger(slot))throw Error('slot must be an integer');chooseTactic(slot);return visibleState();}},{name:'choose_player_attribute',description:'Commit fire 0, leaf 1 or water 2 and resolve the current turn.',inputSchema:{type:'object',properties:{move:{type:'integer',minimum:0,maximum:2}},required:['move'],additionalProperties:false},execute:({move})=>{if(!Number.isInteger(move)||move<0||move>2)throw Error('invalid move');chooseMove(move);return visibleState();}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{} }
try{const response=await fetch('cards.json');if(!response.ok)throw Error('読み込みに失敗しました');data=await response.json();if(data.cards.some((c,i)=>c.id!==i))throw Error('カードデータが不正です');charId=data.cards.find(c=>c.type===0).id;focus=charId;renderSetup();webmcp();}catch(error){app.innerHTML=`<div class="empty"><h1>カードを読み込めませんでした</h1><p>${esc(error.message)}</p><button onclick="location.reload()">再読み込み</button></div>`;}
